package dev.kelmagic.research;
import dev.kelmagic.*;import net.minecraft.world.item.*;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.alchemy.PotionContents;import net.minecraft.world.level.block.entity.BrewingStandBlockEntity;import net.minecraft.server.level.ServerLevel;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=KelMagic.MODID)public final class ResearchBrewing {
 public static boolean magicPotion(ItemStack s){return s.getOrDefault(DataComponents.POTION_CONTENTS,PotionContents.EMPTY).potion().map(p->p.value()==MagicContent.MANA.get()||p.value()==MagicContent.LONG_MANA.get()).orElse(false);}
 public static boolean gated(BrewingStandBlockEntity be){var ingredient=be.getItem(3);for(int i=0;i<3;i++){var potion=be.getItem(i).getOrDefault(DataComponents.POTION_CONTENTS,PotionContents.EMPTY).potion();if(ingredient.is(MagicContent.MANA_CORE)&&potion.map(p->p.value()==net.minecraft.world.item.alchemy.Potions.AWKWARD.value()).orElse(false)||ingredient.is(Items.REDSTONE)&&magicPotion(be.getItem(i)))return true;}return false;}
 public static boolean allowed(ServerLevel l,BrewingStandBlockEntity be){if(be.getItem(3).is(MagicContent.MANA_CORE))return false;String id=be.getData(dev.kelmagic.server.MagicAttachments.RESEARCH_BREWER);try{var p=l.getServer().getPlayerList().getPlayer(java.util.UUID.fromString(id));return p!=null?ResearchCatalog.learned(Research.state(p),"mana_potion"):be.getData(dev.kelmagic.server.MagicAttachments.RESEARCH_BREWING_KNOWN);}catch(IllegalArgumentException e){return false;}}
 public static void authorize(net.minecraft.server.level.ServerPlayer p,BrewingStandBlockEntity be){be.setData(dev.kelmagic.server.MagicAttachments.RESEARCH_BREWER,p.getUUID().toString());be.setData(dev.kelmagic.server.MagicAttachments.RESEARCH_BREWING_KNOWN,ResearchCatalog.learned(Research.state(p),"mana_potion"));be.setChanged();}
 @SubscribeEvent public static void open(net.neoforged.neoforge.event.entity.player.PlayerContainerEvent.Open e){if(e.getEntity() instanceof net.minecraft.server.level.ServerPlayer p&&e.getContainer() instanceof net.minecraft.world.inventory.BrewingStandMenu menu&&menu.getSlot(0).container instanceof BrewingStandBlockEntity be){authorize(p,be);if(gated(be)&&!ResearchCatalog.learned(Research.state(p),"mana_potion"))p.displayClientMessage(net.minecraft.network.chat.Component.literal("Этот настой ещё ждёт своего исследования."),true);}}
 private ResearchBrewing(){}
}
